    // el navegador no lo dispara, hay un cierre de respaldo mas tarde (5s) en vez de 300ms.
    let yaCerro = false;
    const cerrarUnaVez = () => { if (!yaCerro) { yaCerro = true; try { w.close(); } catch (e) {} } };
    w.onafterprint = cerrarUnaVez;
