          <button className="btn btn-g btn-sm" style={{ marginTop: 12 }} onClick={() => setEditandoCuenta({ nombre: "", tipo: "transferencia", banco: "", titular: "", cbu: "", alias: "", solo_acreditacion: false })}>+ Nueva cuenta</button>
